	/**
	 * The first id belonging to {@code type}: the number of accessors declared by all of
	 * its ancestors together.
	 *
	 * <p>Classes that declare none are simply absent from the table and contribute zero,
	 * which is also how vanilla treats them - they never enter its pool, so its walk passes
	 * straight through them.
	 */
	public static int baseIdFor(Class<?> type) {
		int base = 0;
		for (Class<?> c = type.getSuperclass(); c != null; c = c.getSuperclass()) {
			Integer declared = COUNTS.get(c);
			if (declared != null) {
				base += declared.intValue();
			}
			if (c == Entity.class) {
				break;
			}
		}
		return base;
	}

	/** How many accessors {@code type} itself declares; 0 if it declares none. */
	public static int declaredBy(Class<?> type) {
		Integer declared = COUNTS.get(type);
		return declared == null ? 0 : declared.intValue();
	}

